def _make_fast_launcher(self, kernel):
    from torch._C import _FastCudaLauncher

    n_scratch = 0
    if getattr(kernel, "has_global_scratch", False):
        n_scratch += 1
    if getattr(kernel, "has_profile_scratch", False):
        n_scratch += 1
    return _FastCudaLauncher(
        kernel.function, kernel.num_warps, kernel.shared, kernel.arg_tys, n_scratch
    )

@skipIfXpu(msg="https://github.com/pytorch/pytorch/issues/181491")
def test_basic_compile(self):
    """Verify torch.compile uses _FastCudaLauncher and produces correct output."""
    patcher, results = self._patch_build_fast_launcher()
    with patcher:

        @torch.compile
        def foo(x, y):
            return x + y

        x = torch.randn(10, device=GPU_TYPE)
        y = torch.randn(10, device=GPU_TYPE)
        self.assertEqual(foo(x, y), x + y)
        if GPU_TYPE == "xpu":
            self.assertTrue(results, "_build_fast_launcher was not reached on XPU")
            self.assertFalse(
                any(results), "_FastCudaLauncher should not be built on XPU"
            )
        else:
            self.assertTrue(
                any(results),
                "_FastCudaLauncher was not built by any CachingAutotuner",
            )

def statically_launched_kernel_by_device(
    kernel: CompiledKernel, device_type: str = "cuda"
) -> StaticallyLaunchedTritonKernel:
    if device_type in ("cuda", "hip"):
        return StaticallyLaunchedCudaKernel(kernel)
    elif device_type == "xpu":
        return StaticallyLaunchedXpuKernel(kernel)
    else:
        raise NotImplementedError(
            f"Device type {device_type} is not supported for static launcher"
        )

class StaticallyLaunchedCudaKernel(StaticallyLaunchedTritonKernel):
    @cached_property
    def C_impl(self):
        from torch._C import _StaticCudaLauncher

        return _StaticCudaLauncher

    def __init__(self, kernel: CompiledKernel) -> None:
        # pyrefly: ignore [missing-attribute]
        if "hsaco" in kernel.asm:
            # pyrefly: ignore [missing-attribute]
            self.cubin_raw = kernel.asm["hsaco"]

        # pyrefly: ignore [missing-attribute]
        elif "cubin" in kernel.asm:
            # pyrefly: ignore [missing-attribute]
            self.cubin_raw = kernel.asm["cubin"]
        else:
            raise RuntimeError(
                "Expected either 'hsaco' (ROCm) or 'cubin' (CUDA) in kernel.asm"
            )
        super().__init__(kernel)

def _precompile_config(self, cfg: Config) -> TritonCompileResultNpu:
    """Ahead of time compile a given autotuner config."""
    compile_meta = copy.deepcopy(self.triton_meta)
    cfg_kwargs = cfg.kwargs
    constexpr_arg_names = {self.fn.arg_names[i] for i in self.fn.constexprs}
    for k, v in cfg_kwargs.items():
        if k not in constexpr_arg_names:
            continue
        compile_meta["constants"][k] = v

    for i in self.fn.constexprs:
        arg_name = self.fn.arg_names[i]
        if arg_name not in compile_meta["constants"] and (
            arg_name == "num_warps" or arg_name == "num_stages"
        ):
            compile_meta["constants"][arg_name] = getattr(cfg, arg_name)
    compile_meta["num_warps"] = cfg.num_warps
    compile_meta["num_stages"] = cfg.num_stages
    compile_meta["debug"] = (
        os.getenv("INDUCTOR_ASCEND_DEBUG", 'false').lower() in ('true', '1')
        and self.inductor_meta.get("assert_indirect_indexing", True)
        and not self.inductor_meta.get("is_hip", False)
    )

    compile_meta['compile_mode'] = (
        cfg_kwargs.get('compile_mode') or NPUKernelType.SIMT_TEMPLATE.compile_mode()
    )

    # device type will be "hip" rather than "cuda" here
    compile_meta["device_type"] = self.device_props.type
    compile_meta["cc"] = self.device_props.cc

    if not ASTSource:
        raise RuntimeError("Installed triton version too old, please upgrade")

    if compile_meta.get("configs", None):
        compile_args = (
            ASTSource(
                self.fn,
                compile_meta["signature"],
                compile_meta["constants"],
                compile_meta["configs"][0],
            ),
        )
    else:
        compile_args = (
            ASTSource(
                self.fn,
                compile_meta["signature"],
                compile_meta["constants"],
            ),
        )

    cc_warp_size = 32
    target = GPUTarget(
        compile_meta["device_type"],
        compile_meta["cc"],
        cc_warp_size,
    )

    options = {
        "num_warps": compile_meta["num_warps"],
        "num_stages": compile_meta["num_stages"],
        "debug": compile_meta["debug"],
        "compile_mode": compile_meta['compile_mode'],
    }

    options = self.parse_triton_ascend_options(
        self.triton_meta.get("npu_compile_options", {}),
        options,
    )
    options = self.parse_triton_ascend_options(cfg_kwargs, options)
    if (
        bool(self.inductor_meta.get("enable_auto_blockify", False))
        or self.inductor_meta.get("requires_no_linear_block_remap") is True
    ):
        # Older Triton-Ascend versions expose this option. Newer versions
        # manage block mapping internally, so the option is filtered out.
        options = self.parse_triton_ascend_options(
            {"enable_auto_blockify": True}, options
        )

    compile_kwargs = {
        "target": target,
        "options": options,
    }
    start_time = 0
    if log.isEnabledFor(logging.DEBUG):
        start_time = time.perf_counter()
    try:
        binary = None
        binary = triton.compile(*compile_args, **compile_kwargs)
        required_ub_bits = binary.metadata.required_ub_bits
        cfg.real_ub_size = required_ub_bits

    except AttributeError as e:
        # 该错误表示编译无法通过（一些情况下也会被这个Exception捕获）
        log.debug("config: %s compile failed, cost time: %ss", cfg_kwargs, time.perf_counter() - start_time)
        if binary is None:
            raise Exception("Triton compilation failed") from e

        # mistake is metadata no required_ub_bits, but binary work.
        return TritonCompileResultNpu(binary, cfg, compile_meta, self.inductor_meta)

    except Exception:
        log.debug(
            "Triton compilation failed: %s\n%s\nmetadata: %s",
            self.inductor_meta.get("kernel_name", "triton_"),
            self.fn.src,
            compile_meta,
        )
        log.debug("config: %s compile failed, cost time: %ss", cfg_kwargs, time.perf_counter() - start_time)
        import traceback
        ts = traceback.format_exc()
        match = re.search(r"ub overflow.*?requires (\d+) bits", ts)
        if match:
            required_ub_bits = int(match.group(1))
            cfg.real_ub_size = required_ub_bits
        raise
    log.debug("config: %s compile success, cost time: %ss", cfg_kwargs, time.perf_counter() - start_time)
    return TritonCompileResultNpu(binary, cfg, compile_meta, self.inductor_meta)

